/* BNI family logo (BNI Pay / Store / Event / ...). Generated by bni-brand-logo/make_logo.py - regenerate instead of editing.
   Size by WIDTH, never by height: the BNI mark must be the same size on every site. */
export const LOGOS = {
  pay: { src: "/brand/bni-pay-logo.png", width: 600, height: 588, alt: "BNI Pay" },
  store: { src: "/brand/bni-store-logo.png", width: 600, height: 451, alt: "BNI Store" },
  event: { src: "/brand/bni-event-logo.png", width: 600, height: 436, alt: "BNI Event" },
} as const;

export type BrandLogoName = keyof typeof LOGOS;

/** Header / footer width: PC 65.5px, mobile (screen <= 700px) 52px. Tailwind classes. */
export const BRAND_LOGO_WIDTH_CLASS = "w-[52px] min-[701px]:w-[65.5px]";
/** Header bar height: PC 88px, mobile 80px. */
export const BRAND_HEADER_HEIGHT_CLASS = "h-[80px] min-[701px]:h-[88px]";

export function BniBrandLogo({ name, className = BRAND_LOGO_WIDTH_CLASS }: { name: BrandLogoName; className?: string }) {
  const logo = LOGOS[name];
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img src={logo.src} alt={logo.alt} width={logo.width} height={logo.height} className={`block h-auto ${className}`} />
  );
}
